(window.SITE_LANG_DATA = window.SITE_LANG_DATA || {})["no"] = {"ui":{"skip":"Hopp til innholdet","back":"← Tilbake til AI-gile","lang.button":"Språk: {name}","lang.dialog":"Velg et språk","lang.search":"Søk etter språk","lang.none":"Fant ingen språk","lang.notYet":"{name} er ikke oversatt ennå","theme.aria":"Bytt mellom lyst og mørkt tema","theme.toLight":"Bytt til lyst tema","theme.toDark":"Bytt til mørkt tema","index.title":"AI-gile: AI-utviklerteamet ditt, på én tavle","index.description":"AI-gile er en kanban-tavle for AI-kodeteam. De jobber mens du sover; du får én kort bunke med ting du skal bestemme, teste og godkjenne.","hero.logoAlt":"AI-gile-tavleikon","hero.h1.html":"AI-utviklerteamet ditt, på én&nbsp;tavle.","hero.alpha":"🐣 Lukket pre-alfa","hero.alphaTitle":"Tidlig og uferdig: takk for at du prøver!","hero.lede":"De bygger mens du sover. Du våkner til én kort bunke: noen spørsmål, noen ting å teste, en lilla diamant eller to. Klikk, godkjenn, og tilbake til kaffen.","dl.windows":"Windows-app","dl.browser":"Kjør det i nettleseren","dl.soon":"Kommer snart","dl.notify":"🔔 Si fra når det åpner","dl.notifySmall":"Alfa eller beta","hero.secondary":"Agile, men teamet trenger aldri stand-up-kaffe. (De har stand-up likevel.)","pitch.h2":"AI-gile i så mange ord du vil","pitch.lede":"Velg en lengde, fra ett ord til 144. Hver lengde er sin egen beskrivelse, skrevet for akkurat den størrelsen. Dra i glideren eller bruk piltastene.","pitch.rangeLabel":"Lengde i ord","pitch.dice":"🎲 en annen versjon","pitch.words.one":"{n} ord","pitch.words.other":"{n} ord","pitch.letters.one":"{n} bokstav","pitch.letters.other":"{n} bokstaver","pitch.chars.one":"{n} tegn","pitch.chars.other":"{n} tegn","count.line.html.one":"{n} kort på tavlen akkurat nå","count.line.html.other":"{n} kort på tavlen akkurat nå","features.aria":"Hva det gjør","f.pile.h":"Én bunke til deg","f.pile.html":"<b>Til deg</b> samler alt som venter på deg, på tvers av alle prosjekter: spørsmål, ting å teste, oppgaver bare et menneske kan gjøre. Køen din sier hva som er neste og hvor lang tid det tar.","f.sleep.h":"Team som jobber mens du sover","f.sleep.p":"Hvert prosjekt har en lead og et team av AI-agenter. Kommenter et kort, så våkner teamet, gjør jobben og leverer det tilbake med steg som et slitent menneske kan følge.","f.tester.h":"En AI-tester sjekker først","f.tester.p":"Før noe kommer til deg, følger en tester stegene i en kopi av appen og viser hva den så, med skjermbilde. Bla gjennom de som besto og godkjenn med ett klikk.","f.proof.h":"Bevis, ikke løfter","f.proof.p":"Hver levering viser hva som er endret: filene, diffen, skjermbildene. Du slipper å åpne hver app for å se om det er ferdig.","f.chat.h":"Snakk med leadene dine","f.chat.p":"En Discord-lignende sidestolpe: ett ikon per prosjekt, lilla diamanter for det som trenger deg. Send en lead en idé; den gjør den om til kort og en plan, med en ✅ Go-knapp.","f.tidy.h":"Holder orden selv","f.tidy.p":"Beslektede kort slås sammen, rotete titler rettes opp, og en token-sjekk holder koden slank. Færre ting å bytte mellom, mindre å tenke på.","f.private.h":"Ditt, på din egen datamaskin","f.private.li1":"Tavlen kjører på din egen maskin og svarer bare deg.","f.private.li2":"Private meldinger mellom mennesker er ende-til-ende-kryptert.","f.private.li3":"Ingen kontoer, ingen sporere, ingen informasjonskapsler.","f.lang.h":"På ditt språk","f.lang.p":"Over 120 språk, fra norsk, walisisk og japansk til pirat, Yoda og klingon, med en rask bryter tilbake til engelsk for utviklerordene.","tl.aria":"Tidslinje fra den første samtalen til veikartet","tl.h2":"Fra den første praten til det som kommer","tl.lede":"Ekte datoer og klokkeslett, i din egen tidssone. Etter i dag er det planen, uten lovede datoer.","tl.today":"I dag","tl.planned":"planlagt","tl.cards.one":"{n} kort","tl.cards.other":"{n} kort","join.h2":"Bli med","join.lede":"AI-gile bygges av ett lite menneske og et stort antall tålmodige agenter. Foreløpig er det privat, en lukket alfa med venner. Lyst til å prøve når det åpner?","join.btn":"Meld interesse","join.small":"Vi sender deg en e-post, ikke noe mer","footer.tag":"AI-gile. Ingen sporere, ingen informasjonskapsler, ingen stand-up-kaffe.","footer.licence":"Bedriftslisens","footer.status":"Status","form.sending":"Sender…","form.failed":"Det gikk ikke: prøv igjen senere.","form.offline":"Fikk ikke kontakt med AI-gile: prøv igjen senere.","interest.title":"AI-gile: si fra når alfaen åpner","interest.description":"Legg igjen e-postadressen din for å høre når AI-giles lukkede alfa eller beta åpner.","interest.h1":"🔔 Si fra når det åpner","interest.lede":"AI-gile er i lukket pre-alfa. Legg igjen e-postadressen din, så skriver vi én gang, når det er plass til deg.","interest.email":"E-postadressen din","interest.which":"Hvilken test?","interest.alpha":"Lukket alfa: tidlig, grov, mange endringer","interest.beta":"Beta: roligere, senere","interest.both":"Begge deler, det som kommer først","interest.submit":"Sett meg på listen","interest.thanks":"Takk! Du står på listen.","licence.title":"AI-gile: bedriftslisens","licence.description":"Bruker du AI-gile i bedriften din? Søk om en gratis bedriftslisens.","licence.h1":"📜 Bedriftslisens","licence.lede":"Bruker du AI-gile på jobb? Fortell oss hvem du er og hva du gjør. Hvis det gjør noe godt, er lisensen gratis.","licence.company":"Bedrift","licence.website":"Nettsted","licence.what":"Hva du gjør","licence.how":"Hvordan det hjelper verden","licence.email":"E-post","licence.submit":"Søk","licence.thanks":"Takk! Vi svarer på e-post.","status.title":"AI-gile-status","status.h1":"AI-gile-status","status.quiet":"Alt er rolig","status.checking":"Sjekker…","status.offline":"Får ikke kontakt med statustjenesten akkurat nå (prøver igjen)","status.updated":"oppdatert {ago}","status.justNow":"nå nettopp","status.min":"{n} min siden","status.hours":"{n} t siden","status.days":"{n} d siden","live.h2":"Se det bli bygget, direkte","live.caption":"Hvert kort er skjult: du ser formen på arbeidet, ikke ordene.","live.watching.one":"direkte: {n} ser på","live.watching.other":"direkte: {n} ser på","live.offline":"Direktetavlen tar en liten pause. Kom innom igjen snart.","live.cols":"Backlog|Å gjøre|Pågår|Teamet sjekker|Du skal teste|Til teamet|Ferdig","live.last.now":"Siste kort ble flyttet nettopp","live.last.min.one":"Siste kort ble flyttet for {n} min. siden","live.last.min.other":"Siste kort ble flyttet for {n} min. siden","live.last.hour.one":"Siste kort ble flyttet for {n} time siden","live.last.hour.other":"Siste kort ble flyttet for {n} timer siden","live.last.day.one":"Siste kort ble flyttet for {n} dag siden","live.last.day.other":"Siste kort ble flyttet for {n} dager siden"},"lines":{"unit":"words","sizes":[{"n":1,"texts":["Kanban.","Roboter.","Delegert."]},{"n":2,"texts":["Roboter jobber.","Agenter, ordnet.","Idéer, bygget."]},{"n":3,"texts":["Kanban for roboter.","Idéer blir funksjoner.","Gratis, lokalt, testet."]},{"n":5,"texts":["En kanban-tavle der agentene bygger.","Du skriver kort. Agenter bygger.","Gratis, lokalt, testet, litt tullete."]},{"n":8,"texts":["En gratis kanban-tavle der AI-agenter gjør selve jobben.","Skriv en idé. Agentene bygger den. Du godkjenner.","Agile for ett menneske og mange tålmodige roboter."]},{"n":13,"texts":["En kanban-tavle på datamaskinen din der AI-agenter plukker opp kortene.","Skriv en idé. Et team av agenter bygger den. En tester sjekker den.","Gratis, ingen kontoer, ingen sporere: en tavle, noen roboter, og du som sjef."]},{"n":21,"texts":["AI-gile er en kanban-tavle for å jobbe med AI-kodeagenter. De plukker opp kortene; du tester og godkjenner dem.","Hvert prosjekt får en lead og et team av AI-agenter. Kommenter hvilket som helst kort, så setter teamet i gang.","En gratis, personlig oppgavetavle som kjører på din egen datamaskin. Arbeiderne er roboter. Den som sier ja, er du."]},{"n":34,"texts":["Du legger idéer på en tavle. Et team av AI-agenter gjør dem om til fungerende funksjoner, tester dem og leverer dem tilbake med steg du kan prøve. Ingenting regnes som ferdig før du sier det.","AI-gile er en hjemmelaget kanban-tavle som Rich bygde med mye hjelp fra agentene den nå styrer. Den er gratis, kjører på datamaskinen din og deles med venner, ikke selges.","Tenk deg en vanlig kanban-tavle, med kolonner fra Backlog til Ferdig, bare at kortene plukkes opp av AI-agenter. De rapporterer framdrift, spør når de står fast, og venter alltid på tommelen opp fra deg."]},{"n":55,"texts":["AI-gile er en kanban-tavle der teamet består av AI-agenter. Hvert prosjekt har en lead som planlegger arbeidet og hjelpere som bygger det. Når en funksjon er klar, prøver en AI-tester den og tar et skjermbilde, og så havner den i bunken din. Godkjenn den, eller kommenter, så jobber de om den.","Det begynte som én persons måte å holde styr på mange AI-kodeøkter samtidig, og vokste til en ordentlig tavle. Den kjører på maskinen din, krever ingen konto og har ingen sporere. Den er gratis for venner og nysgjerrige. Den er også uferdig, så regn med noen skarpe kanter og en og annen overraskelse.","Her er den ærlige versjonen. Du må fortsatt komme med idéene, og du må fortsatt sjekke resultatene. Det AI-gile gjør, er alt imellom: det holder kortene i orden, vekker riktig agent når du kommenterer, viser nøyaktig hva som er endret, og samler alt i én kort bunke til deg."]},{"n":89,"texts":["AI-gile er en gratis kanban-tavle som du kjører på din egen datamaskin. I stedet for mennesker har hvert prosjekt et team av AI-agenter: en lead som gjør idéene dine om til kort og en plan, og hjelpere som plukker opp kortene i prioritert rekkefølge. Når noe er bygget, følger en AI-tester teststegene og viser deg hva den så. Så venter det i én bunke som heter Til deg. Du godkjenner det, eller du kommenterer og teamet prøver på nytt. Ingenting havner noen gang i Ferdig uten deg.","Noen funksjoner du kanskje ikke venter. En nattevakt holder Å gjøre-kolonnen fylt opp mens du sover, og velger kort som ikke trenger svar fra deg. En tokenteller viser hvor mye agentene har brukt i dag og denne uka, og Ingen token-modus ber dem slutte å bruke. Du kan sende meldinger til venner, og private meldinger er ende-til-ende-kryptert. Tavlen snakker rundt 120 språk, blant andre norsk, pirat og klingon. Ingenting av det koster en krone, og ingen prøver å selge det til deg heller.","AI-gile er et lite, personlig prosjekt, ikke et selskap. Rich ville ta vare på flere AI-kodeprosjekter uten å åpne hver app for å sjekke dem, så han og agentene bygde en tavle til det, og brukte så tavlen til å bygge resten av seg selv. Den er i lukket pre-alfa, som betyr at den virker, stort sett, for en håndfull venner. Det finnes ingen prisside, ingen nyhetsbrev og ingen vekstplan. Høres det nyttig ut, kan du be om å få prøve den når den åpner litt mer."]},{"n":144,"texts":["AI-gile er en kanban-tavle for ett menneske og mange AI-agenter. Den kjører på din egen datamaskin og er helt gratis. Du legger til prosjekter, og hvert prosjekt får en lead og et lite team. Du prater med leaden, litt som på Discord, og beskriver en idé; leaden gjør den om til kort og en plan, og venter på at du trykker Go. Teamet jobber seg gjennom kortene i prioritert rekkefølge, med et enkelt kommandolinjeverktøy laget for språkmodeller. Før noe kommer tilbake til deg, følger en AI-tester stegene i en kopi av appen og legger ved et skjermbilde. Ferdig arbeid havner i bunken din, med de endrede filene og diffen. Du godkjenner det, eller du legger igjen en kommentar, så våkner teamet og prøver på nytt. Bare du kan flytte et kort til Ferdig.","En dag med AI-gile, omtrent. Om kvelden legger du igjen noen kommentarer: denne knappen står på feil sted, den listen bør sorteres, kunne vi fått mørk modus. Du går og legger deg. Agentene leser kommentarene, gjør endringene, tester dem og leverer dem tilbake til deg. Hvis Å gjøre går tom, fyller nattevakten opp fra backlogen med kort som ikke trenger noe svar fra deg. Om morgenen ligger det én kort bunke: et par spørsmål og noen ting å prøve, hver med steg som en søvnig person kan følge og et skjermbilde av at det virker. Du klikker deg gjennom, godkjenner de gode og sender resten tilbake. En tokenteller viser hva det hele brukte, og Ingen token-modus finnes for magre uker. Så spiser du frokost, noe agentene ikke kan hjelpe med ennå.","Først, hva AI-gile ikke er. Det er ikke en oppstartsbedrift, det er ikke til salgs, og ingen samler inn dataene dine. Det er en gratis tavle som kjører på datamaskinen din, uten kontoer, sporere eller informasjonskapsler. Det det er: ett ryddig sted å se alle AI-kodeprosjektene dine samtidig, med et team av agenter som tar kortene og du som tar avgjørelsene. Det slår sammen beslektede kort, retter opp rotete titler og følger med på hvor slank koden holder seg. Det snakker rundt 120 språk, fra norsk til pirat og klingon. Venner kan sende hverandre meldinger, privat og kryptert. Det er bygget av Rich og et stort antall tålmodige agenter, som for det meste brukte det selv. Det er i lukket pre-alfa, så det er grovt noen steder. Høres det gøy ut, spør pent, så kommer du kanskje tidlig inn."]}],"quips":{"1":"Ett ord. Frekt. Kanskje for frekt.","3":"Tre ord. Allerede ærligere enn de fleste produktsider.","8":"Åtte ord. Fortsatt kortere enn en stand-up.","21":"Lengdene er forresten story points. Selvfølgelig er de det.","55":"Femtifem ord. To kort ble ferdige mens du leste det.","144":"Det var den lange. Det finnes ingen 233. Agentene har gått og lagt seg."}},"timeline":{"first-idea.name":"Den første idéen","first-idea.line":"Den aller første samtalen, før det fantes en eneste linje kode.","first-board.name":"Første tavle","first-board.line":"En tavle som holder styr på sin egen bygging: kort, kolonner, dra og slipp, prosjekter.","team-roles.name":"Team og roller","team-roles.line":"Agentprofiler, teammaler, rom og hvem som gjør hva.","install.name":"Installering og utgivelser","install.line":"En zip-fil en venn kan installere, selvoppdatering, kanaler og tilbakerulling.","usage-saver.name":"Bruksbesparer","usage-saver.line":"Måle hva kjøringer koster, holde koden slank, spare på grensen din.","friends.name":"Venner og deling","friends.line":"Private meldinger, et kryptert relé, invitasjoner, roller og delte prosjekter.","languages.name":"Språk","languages.line":"Hver skjermtekst i en språkfil, med nederlandsk og flamsk først.","ai-tester.name":"AI-tester","ai-tester.line":"En tester sjekker hver levering først og viser hva den så.","website.name":"Nettstedet","website.line":"aigile.lol, teaseren og denne tidslinjen.","streaming.name":"Chat og streaming","streaming.line":"Discord, Twitch, OBS, strømmermodus, GIF-er og emojier.","no-ai.name":"Utgave uten AI","no-ai.line":"En tavle for folk som koder uten AI, og offentlige tavler.","night-watch.name":"Nattevakt","night-watch.line":"En vaktmann og en Scrum Master holder teamene på sporet mens du sover.","p-more.name":"Alt det andre","p-more.line":"Mindre idéer som fortsatt venter på tur.","p-android.name":"Telefon og Android","p-android.line":"Nå tavlen din fra telefonen, deretter en egen Android-app.","p-release.name":"Alfa og videre","p-release.line":"Lukket alfa, det levende nettstedet, så beta.","p-languages.name":"Flere språk","p-languages.line":"Mer enn hundre språk, og en fordypningsmodus for dem som lærer.","p-engines.name":"Flere AI-motorer","p-engines.line":"Velg Claude, Codex eller Gemini for hver agent.","p-pro.name":"Profesjonell praksis","p-pro.line":"Risikomerker, sammenslåingsporter, hendelseskort og rekkverk.","p-self.name":"Å ta vare på deg","p-self.line":"Trøtt modus, egenomsorgspåminnelser og 4:20.","p-servers.name":"Servere og skalering","p-servers.line":"Globale serverinnstillinger, roller og planlegging for vekst.","p-livestream.name":"Streamingtillegg","p-livestream.line":"Twitch-chat, egne emojier og en offentlig direktevisning."}};
